// PLAT-006 — versioned migrations (generated by drizzle-kit from modules/*/schema.ts).
import { existsSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { migrate as migratePg } from 'drizzle-orm/node-postgres/migrator';
import { migrate as migratePglite } from 'drizzle-orm/pglite/migrator';
import type { Config } from './config.js';
import type { DbHandle } from './db.js';

/** apps/api/drizzle — the same relative location from src/core and dist/core. */
export const MIGRATIONS_DIR = fileURLToPath(new URL('../../drizzle', import.meta.url));

export interface MigrateOptions {
  /** Schema for drizzle's bookkeeping table (isolated test schemas use their own). */
  migrationsSchema?: string;
}

export async function runMigrations(
  handle: DbHandle,
  folder: string = MIGRATIONS_DIR,
  opts: MigrateOptions = {},
): Promise<'migrated' | 'no-migrations'> {
  // drizzle-kit writes meta/_journal.json with the first migration; before that there is nothing to do.
  if (!existsSync(join(folder, 'meta', '_journal.json'))) return 'no-migrations';
  const config = { migrationsFolder: folder, ...opts };
  if (handle.kind === 'pglite') await migratePglite(handle.raw, config);
  else await migratePg(handle.raw, config);
  return 'migrated';
}

/** PLAT-006/AC4 — called by main.ts before the server listens. */
export async function migrateOnStart(
  config: Config,
  handle: DbHandle,
  folder: string = MIGRATIONS_DIR,
): Promise<'migrated' | 'no-migrations' | 'skipped'> {
  if (!config.DB_MIGRATE_ON_START) return 'skipped';
  return runMigrations(handle, folder);
}
